def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_c = 0
    for me, opp in history:
        if opp == 'C':
            opp_c += 1
    opp_d = n - opp_c

    if opp_c == 0:
        if n < 5:
            return 'C'
        else:
            return 'D'

    last_opp = history[-1][1]
    if last_opp == 'C':
        return 'C'

    window = min(10, n)
    recent_d = 0
    for i in range(n - window, n):
        if history[i][1] == 'D':
            recent_d += 1

    if recent_d <= 1:
        return 'C'
    if opp_d <= 2:
        return 'C'
    if rng.random() < 0.1:
        return 'C'
    return 'D'
